let state;try{state=JSON.parse(localStorage.getItem('discrete-v1'))||{done:[],answers:{}}}catch{state={done:[],answers:{}}}const app=document.querySelector('#app');const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function save(){try{localStorage.setItem('discrete-v1',JSON.stringify(state))}catch{}document.querySelector('#wc').textContent=Object.values(state.answers).filter(x=>!x.correct).length}function nav(){let s=document.querySelector('#search').value.toLowerCase(),g='';document.querySelector('#nav').innerHTML='<a href="#home">⌂ 学习概览</a>'+lessons.filter(l=>(l.title+l.body).toLowerCase().includes(s)).map(l=>{let h=l.group!==g?`<h4>${g=l.group}</h4>`:'';return h+`<a class="${location.hash==='#lesson-'+l.id?'active':''}" href="#lesson-${l.id}">${String(l.id+1).padStart(2,'0')}　${l.title}${state.done.includes(l.id)?' ✓':''}</a>`}).join('')}function home(){document.querySelector('#crumb').textContent='学习概览';let next=lessons.find(l=>!state.done.includes(l.id))||lessons[0];app.innerHTML=`<section class="hero"><div><span class="eyebrow">A LITTLE LOGIC, EVERY DAY</span><h1>把离散的知识，<br>连成清晰的思路。</h1><p>从一个命题，到一张图，再到抽象的代数结构。沿着你的笔记循序渐进，在每一次练习中理解数学的语言。</p><div class="actions"><a class="button primary" href="#lesson-${next.id}">继续学习 · ${next.title} →</a><a class="button" href="#catalog">浏览课程目录</a></div></div><div class="art">∀ → ∞</div></section><div class="stats"><div><strong>17</strong><span>笔记章节</span></div><div><strong>34</strong><span>精选练习</span></div><div><strong>${state.done.length}/17</strong><span>已学章节</span></div></div><section><span class="eyebrow">YOUR LEARNING PATH</span><h2>每一章，都走稳四步</h2><p>① 阅读概念与公式　→　② 跟随例题理解　→　③ 独立完成练习　→　④ 对照解析与原笔记</p></section><section id="catalog"><h2>课程目录 <small class="tag">按笔记顺序 · 四个学习模块</small></h2><div class="grid">${lessons.map(l=>`<a class="card" href="#lesson-${l.id}"><span class="num">CHAPTER ${String(l.id+1).padStart(2,'0')}　${state.done.includes(l.id)?'✓ 已学':''}</span><h3>${l.title}</h3><p>${l.intro}</p><span class="tag">${l.group} · 笔记 ${l.start}–${l.end} 页　↗</span></a>`).join('')}</div></section><section class="box"><h3>内容说明与学习建议</h3><p>本学习站依据手写笔记的17章标题与页码建立导航，讲解与练习为原创入门导学，未逐页转录全部手写推导。原笔记分章提供，遇到详细定理与证明可直接对照阅读。</p><p>“屈版”存在不同版本，暂按笔记的章节顺序组织，不声称与某一版教材章号完全一致。参照屈婉玲等著《离散数学》的知识体系；教材中的组合数学、完整谓词逻辑等未在此单独设章，后续可按指定版本扩展。</p><a href="https://www.hep.com.cn/book/show/2d67dc4c-217a-41db-81b2-56bfe7428879" target="_blank" rel="noopener">教材信息 · 高等教育出版社 ↗</a><p class="note">进度与错题仅保存在当前浏览器。建议每次学习1章，先作答，再查看解析。</p></section>`}function question(l,q,i){let key=l.id+'-'+i;return `<div class="box"><span class="tag">${i===0?'单项选择':'填空题'} · ${l.title}</span><h3>${esc(q.q)}</h3><form data-key="${key}">${q.options?q.options.map((o,j)=>`<label class="option"><input type="radio" name="answer" value="${j}" required>${String.fromCharCode(65+j)}. ${esc(o)}</label>`).join(''):'<label>你的答案（填写一个整数） <input name="answer" inputmode="numeric" autocomplete="off" required></label>'}<div class="actions"><button class="primary" type="submit">提交答案</button><button type="button" data-explain="${key}">查看解析</button></div><div class="feedback" aria-live="polite" id="feedback-${key}"></div></form></div>`}function lesson(id){let l=lessons[id];if(!l){location.hash='home';return}document.querySelector('#crumb').textContent=l.title;app.innerHTML=`<article class="lesson"><span class="eyebrow">CHAPTER ${String(id+1).padStart(2,'0')} / ${l.group}</span><h1>${l.title}</h1><p>${l.intro}</p><div class="actions"><a class="button" href="notes/${id+1}.pdf" target="_blank">阅读原笔记 · 第${l.start}–${l.end}页 ↗</a><a class="button" href="#practice">进入练习 ↓</a></div><section class="box"><span class="tag">01 / 理解概念</span><h2>核心知识</h2><p>${l.body}</p><div class="formula">${l.formula}</div></section><section class="box"><span class="tag">02 / 跟随例题</span><h2>把定义用起来</h2><p>${l.example}</p></section><div class="warn"><strong>易错提醒</strong><br>${l.pitfall}</div><section id="practice"><span class="tag">03 / 独立练习</span><h2>现在，检验你的理解</h2>${l.questions.map((q,i)=>question(l,q,i)).join('')}</section><div class="actions"><button class="primary" id="done">${state.done.includes(id)?'已标记学完 ✓':'标记本章学完 ✓'}</button>${id<16?`<a class="button" href="#lesson-${id+1}">下一章 →</a>`:'<a class="button" href="#home">返回概览</a>'}</div></article>`;document.querySelector('#done').onclick=()=>{if(!state.done.includes(id))state.done.push(id);save();nav();document.querySelector('#done').textContent='已标记学完 ✓'}}function explain(key,prefix=''){let [id,i]=key.split('-').map(Number),q=lessons[id].questions[i];document.getElementById('feedback-'+key).textContent=prefix+'答案：'+(q.options?String.fromCharCode(65+Number(q.answer))+'. '+q.options[q.answer]:q.answer)+'\n解析：'+q.why}app.addEventListener('submit',e=>{e.preventDefault();let key=e.target.dataset.key,[id,i]=key.split('-').map(Number),value=new FormData(e.target).get('answer').trim().replace(/[０-９]/g,c=>String(c.charCodeAt(0)-65296));let correct=value===lessons[id].questions[i].answer;state.answers[key]={correct,value};save();explain(key,correct?'✓ 回答正确。\n':'再想一想。\n');document.getElementById('feedback-'+key).className='feedback '+(correct?'correct':'incorrect')});app.addEventListener('click',e=>{let b=e.target.closest('[data-explain]');if(b)explain(b.dataset.explain)});document.querySelector('#wrong').onclick=()=>{location.hash='wrong'};document.querySelector('#search').oninput=nav;function route(){if(location.hash==='#practice'||location.hash==='#catalog')return;nav();if(location.hash.startsWith('#lesson-'))lesson(Number(location.hash.slice(8)));else if(location.hash==='#wrong'){document.querySelector('#crumb').textContent='错题回顾';let keys=Object.keys(state.answers).filter(k=>!state.answers[k].correct);app.innerHTML='<section class="lesson"><h1>把疑惑，变成理解。</h1><p>重新作答正确后，题目会从下次错题回顾中移除。</p>'+ (keys.length?keys.map(k=>{let [id,i]=k.split('-').map(Number);return question(lessons[id],lessons[id].questions[i],i)}).join(''):'<div class="box">目前没有错题。去课程中完成练习吧。</div>')+'</section>'}else home();window.scrollTo(0,0)}window.onhashchange=route;save();route();
